import{S as i}from"./chunks/SchedulingLab.CS8ngyIV.js";import{C as s,o as d,c as l,j as a,a as r,E as t,a6 as n}from"./chunks/framework.CIQdaWiD.js";import"./chunks/usePlayback.DoA8ctHb.js";const g=JSON.parse('{"title":"計時器與 RR 排程","description":"","frontmatter":{},"headers":[],"relativePath":"topics/scheduling.md","filePath":"topics/scheduling.md","lastUpdated":1795330291000}'),c={name:"topics/scheduling.md"},f=Object.assign(c,{setup(h){return(p,e)=>{const o=s("MermaidDiagram");return d(),l("div",null,[e[0]||(e[0]=a("h1",{id:"_05-·-計時器與-rr-排程",tabindex:"-1"},[r("計時器與 RR 排程 "),a("a",{class:"header-anchor",href:"#_05-·-計時器與-rr-排程","aria-label":'Permalink to "計時器與 RR 排程 {#_05-·-計時器與-rr-排程}"'},"​")],-1)),e[1]||(e[1]=a("p",null,[r("對應現行規格："),a("a",{href:"./../spec/04-scheduling.html"},"〈04 · 誰先跑：排程、狀態與多 Hart〉"),r("。")],-1)),t(i),e[2]||(e[2]=n('<p>目前排程單位是 TCB，同一 Process 可有多條 Thread，各自參與 Ready queue 輪轉。上方互動模型以 PID 標示獨立 CPU 工作負載，不是完整多 Thread 模型，也不改變核心固定 50 ms 的政策。等待、喚醒與退出請看 <a href="./threads.html">Thread 狀態圖解</a>；實作與驗收邊界見 <a href="./../thread-stage-b.html">B／C 紀錄</a>。</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><strong>WUWAOS 目前使用固定 50 ms 時間片的 RR（Round Robin，輪詢排程）</strong>。Ready Thread 以 FIFO（先進先出）順序排隊；在使用者模式執行的 Thread 若時間片到期，核心將它排回隊尾，再派發下一條。每條 Thread 各自排隊，不保證每 Process 平分時間片。互動圖使用固定的小型工作負載說明 RR 計算，不讀即時 OS 狀態。</p><p>派發機制已改為 <a href="./processes.html#核心函式如何暫停與恢復">Spec 16 的核心上下文切換</a>：透過 <code>swtch.S</code> 往返獨立排程器堆疊，保存暫停中的核心函式；50 ms RR 政策維持不變。</p><p>RR 是先進先出的 ready queue 加上有限時間片。行程用完時間片仍未完成，就回到隊尾；若提早完成、阻塞或主動 yield，則不會佔住 CPU 等到 quantum 用盡。教材工作負載刻意只包含 arrival 與 CPU burst，沒有 I/O、優先權、多核心或核心執行成本。</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><h3 id="硬體如何讓使用者程式暫停" tabindex="-1">硬體如何讓使用者程式暫停 <a class="header-anchor" href="#硬體如何讓使用者程式暫停" aria-label="Permalink to &quot;硬體如何讓使用者程式暫停&quot;">​</a></h3><p>核心透過 OpenSBI TIME（韌體計時服務）設定「目前硬體時間 + 50 ms」。到期後，CPU 收到 Supervisor timer interrupt（監督模式計時器中斷），跳到 <code>stvec</code>（監督模式陷阱入口暫存器）指定的入口。</p>',8)),t(o,{source:`flowchart TD
  A[從就緒隊首取出 Thread] --> B[設定時間片：現在 + 50 ms]
  B --> C[sret：恢復暫存器，執行使用者程式]
  C --> D[時間到：CPU 進入 trap_entry]
  D --> E[保存 TrapFrame，辨識計時器中斷]
  E --> F[SBI 清除 pending，Running 改為 Ready]
  F --> G[原 Thread 排入隊尾]
  G --> A
`}),e[3]||(e[3]=n('<p>硬體不需要等待程式呼叫函式。<code>sepc</code>（保存的執行位置）已是恢復位置，不能像 <code>ecall</code> 那樣加 4；<code>a0</code>（參數／返回值暫存器）也必須原樣保留。</p><h3 id="ready-queue-與-rr-輪轉" tabindex="-1">Ready queue 與 RR 輪轉 <a class="header-anchor" href="#ready-queue-與-rr-輪轉" aria-label="Permalink to &quot;Ready queue 與 RR 輪轉&quot;">​</a></h3><p>Ready queue（就緒佇列）只串接 Ready TCB（執行緒控制區塊）。head／tail（隊首／隊尾）讓入列與取隊首為 O(1)，移除特定節點最壞 O(N)。Running、Waiting、Zombie 不留在佇列；<code>ready_queued</code> 避免重複入列。</p>',3)),t(o,{source:`flowchart TD
  A[A 執行；佇列 B → C] -->|50 ms 到期| B[B 執行；佇列 C → A]
  B -->|50 ms 到期| C[C 執行；佇列 A → B]
  C -->|50 ms 到期| A
`}),e[4]||(e[4]=n(`<p>只有一條可執行 Thread 時，它可重新獲選並取得下一個時間片。喚醒與新建 Thread 排隊尾，不立刻搶走目前尚未到期的時間片。</p><h2 id="step-by-step" tabindex="-1">Step-by-step <a class="header-anchor" href="#step-by-step" aria-label="Permalink to &quot;Step-by-step&quot;">​</a></h2><p>下方示例固定三個工作：A 在 0 ms 抵達、burst 95 ms；B 在 25 ms 抵達、burst 60 ms；C 在 40 ms 抵達、burst 35 ms。可將教學 quantum 調為 25、50 或 100 ms，或逐步播放 queue、remaining 與 Gantt。每個 frame 是某個 slice 執行結束、期間到達的工作入列、未完成工作回到隊尾後的狀態；時間線只顯示已執行的 slice。</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><h3 id="派發與時間片" tabindex="-1">派發與時間片 <a class="header-anchor" href="#派發與時間片" aria-label="Permalink to &quot;派發與時間片&quot;">​</a></h3><p>每次派發 Thread 時，scheduler 從 queue head 移除它、將狀態轉成 Running，計數 dispatch，選擇其所屬 Process 的頁表並設定 50 ms timer。時間片到期後，timer trap 呼叫 <code>thread_preempt()</code>：目前 Thread 計數 preemption、轉回 Ready（因此入隊尾），停止 timer，保存工作狀態後切回 scheduler stack。<code>context_switch</code> 保存的是一般 C 呼叫邊界的 callee-saved state；完整使用者 TrapFrame 由 trap 路徑另外保存。</p><h3 id="系統呼叫、yield-與阻塞" tabindex="-1">系統呼叫、yield 與阻塞 <a class="header-anchor" href="#系統呼叫、yield-與阻塞" aria-label="Permalink to &quot;系統呼叫、yield 與阻塞&quot;">​</a></h3><p>普通 syscall 或合法缺頁處理完，若原 Thread 仍是 Running，就保留原 deadline（到期時間）。因此不停呼叫 <code>getpid</code> 也不能讓時間片一直歸零。</p><p><code>yield</code>（主動讓出）會放棄剩餘時間並排隊尾；阻塞或退出也放棄時間片。重新被派發時才取得新的 50 ms，不累積未用完的預算。</p><h3 id="ready-queue-實作" tabindex="-1">Ready queue 實作 <a class="header-anchor" href="#ready-queue-實作" aria-label="Permalink to &quot;Ready queue 實作&quot;">​</a></h3><p>scheduler queue 使用 head、tail 與 count。enqueue 對已在佇列的 TCB 不重複加入；<code>scheduler_next</code> 移除 head 並清除 TCB 的 queue link/flag；指定 TCB 的移除則沿鏈結尋找前節點。<code>thread_transition</code> 擁有 enqueue/remove 呼叫，避免排程策略與狀態更新分家。</p><h3 id="在-qemu-觀察" tabindex="-1">在 QEMU 觀察 <a class="header-anchor" href="#在-qemu-觀察" aria-label="Permalink to &quot;在 QEMU 觀察&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps</span></span>
<span class="line"><span>run counter</span></span>
<span class="line"><span>run counter</span></span>
<span class="line"><span>wakeup 9</span></span>
<span class="line"><span>ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>ps</code> 列出 RR、<code>quantum_ms=50</code>、<code>timer_interrupts</code> 與就緒順序；PCB 加上 <code>dispatches</code>（派發次數）與 <code>preemptions</code>（時間片到期次數）。依實際 PID 執行 <code>pcb &lt;pid&gt;</code> 與 <code>wait &lt;pid&gt;</code>。</p><p>counter 每輪會 yield，交替輸出只能展示輪轉，不能單憑它證明計時器搶占。真正的無 yield 驗證透過 QEMU 偵錯介面讓既有 worker 執行映像中已存在的迴圈，沒有新增測試程式，見 <a href="./../SPEC-15-timer-rr.html">Spec 15</a>。短程式可能在時間片前結束，中斷數為 0 也正常。</p><h2 id="source-mapping" tabindex="-1">Source mapping <a class="header-anchor" href="#source-mapping" aria-label="Permalink to &quot;Source mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模組</th><th>責任與原始碼</th></tr></thead><tbody><tr><td>Clock（硬體時間）</td><td><a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/clock.h" target="_blank" rel="noreferrer">clock.h</a>：<code>rdtime</code>、10 MHz 時基、毫秒換算，動畫與磁碟逾時共用</td></tr><tr><td>SBI（韌體介面）</td><td><a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/sbi.c" target="_blank" rel="noreferrer">sbi.c</a>：查詢 TIME 支援並設定絕對到期時間</td></tr><tr><td>Timer（計時器）</td><td><a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/timer.c" target="_blank" rel="noreferrer">timer.c</a>：設定／停用事件、清除 pending（待處理中斷）、累計中斷數</td></tr><tr><td>Timer API</td><td><a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/timer.h" target="_blank" rel="noreferrer">timer.h</a>：timer start/stop/interrupt 介面</td></tr><tr><td>Scheduler（排程器）</td><td><a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/proc/scheduler.c" target="_blank" rel="noreferrer">scheduler.c</a>：FIFO ready queue；<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/proc/scheduler.h" target="_blank" rel="noreferrer">scheduler.h</a>：固定 <code>SCHEDULER_QUANTUM_MS = 50</code></td></tr><tr><td>Process（行程管理）</td><td><a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/proc/process.c" target="_blank" rel="noreferrer">process.c</a>：狀態、派發、yield/preempt、頁表與保存狀態</td></tr><tr><td>Trap（陷阱分派）</td><td><a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/trap.c" target="_blank" rel="noreferrer">trap.c</a>：辨識 timer interrupt 並呼叫 <code>thread_preempt</code></td></tr><tr><td>Context switch</td><td><a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/context.h" target="_blank" rel="noreferrer">context.h</a> 與 <a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/swtch.S" target="_blank" rel="noreferrer">swtch.S</a>：保存／還原 <code>ra</code>、<code>sp</code> 與 <code>s0–s11</code></td></tr></tbody></table><h2 id="failures-limitations" tabindex="-1">Failures / Limitations <a class="header-anchor" href="#failures-limitations" aria-label="Permalink to &quot;Failures / Limitations&quot;">​</a></h2><h3 id="核心為什麼仍不搶占" tabindex="-1">核心在哪裡可以被搶占 <a class="header-anchor" href="#核心為什麼仍不搶占" aria-label="Permalink to &quot;核心在哪裡可以被搶占 {#核心為什麼仍不搶占}&quot;">​</a></h3><p>初始使用者狀態設 <code>sstatus.SPIE</code>（陷阱返回後中斷啟用狀態），並開啟 <code>sie.STIE</code>（允許計時器中斷）。進入核心後通常關閉 <code>SIE</code>。系統呼叫完成後，有一個短暫的搶占檢查點。沒有持有內部 Gate、延後取消或待處理的 kill 時，核心才在這個檢查點接受計時器中斷。</p><p>多 Hart 透過共享核心鎖協調頁表、行程表與 VirtIO 佇列的核心操作。Gate 競爭與 Block request 都可讓呼叫者透過事件等待交還 CPU，裝置完成後再恢復原呼叫。開機仍可同步輪詢。長 syscall、CPU 繪圖與大量記憶體複製可能延後搶占，實際回應時間會受這些工作影響。</p><p>若沒有 Ready 行程但仍有 event 或 UI poll work，排程器使用固定的短絕對 deadline arm SBI timer，於 <code>SIE=0</code> 下執行 <code>WFI</code>；<code>sie.STIE</code> 保持開啟，因此本地 timer pending 可喚醒 WFI，而 trap handler 不會進入 S-mode timer interrupt。返回後先停止／確認 timer，再輪詢 UART、UI 與 event timeout。Spurious wake 會沿用原絕對 deadline，避免無限延後。這是 idle polling 節能等待，不改 50 ms RR quantum，也不是裝置中斷驅動。</p><h3 id="教學模型與核心的差異" tabindex="-1">教學模型與核心的差異 <a class="header-anchor" href="#教學模型與核心的差異" aria-label="Permalink to &quot;教學模型與核心的差異&quot;">​</a></h3><p>互動元件重算的是固定 arrival/burst 工作負載；quantum 可調是為了比較 RR 行為，並不呼叫核心、不取得 <code>ps</code>/<code>workstate</code> 統計，也不改核心 timer 常數。模型假設單核心、CPU-only burst，沒有 I/O 阻塞、核心工作成本、wake-up、yield、中斷延遲或多核心競爭；Gantt 寬度表示模型毫秒，不是真實 CPU 統計。</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li>課程筆記的「RR 核心定義與硬體依賴」一節介紹 Round-Robin 與 FIFO queue。本站互動器以有限 workload 示範這些概念，WUWAOS 的核心實作見上方原始碼。 <a href="https://github.com/johnson931128/WUWAOS/blob/main/notes/ch5%20CPU%20schedueling.md" target="_blank" rel="noreferrer">notes/ch5 CPU schedueling.md</a></li><li>歷史設計見 <a href="./../SPEC-07-fifo-scheduler.html">Spec 07</a> 與 <a href="./../SPEC-15-timer-rr.html">Spec 15</a>，目前的多 Hart 與搶占規則見<a href="./../spec/04-scheduling.html">排程規格</a>。</li><li><a href="https://research.cs.wisc.edu/wind/OSTEP/cpu-sched.pdf" target="_blank" rel="noreferrer">OSTEP CPU Scheduling</a> §7.7：RR time slice 與工作負載推演。</li><li><a href="https://srg-ics-uplb.github.io/cmsc125/viztools/scheduling/" target="_blank" rel="noreferrer">OSTEP VizTools Scheduling</a> 與 <a href="https://oslab.xikai.me/cpu-scheduling" target="_blank" rel="noreferrer">OS Lab CPU Scheduling</a>：互動步驟與 queue/Gantt 視圖參考。</li></ul><p>RR 決定誰取得 CPU；<a href="./paging.html">頁面置換 FIFO</a> 決定誰讓出實體頁框。CPU 政策改變，不會把記憶體置換也改成 RR。尚無優先權、多核心排程、核心內搶占與完整終端工作控制。</p>`,27))])}}});export{g as __pageData,f as default};
